import { G } from './state.js';
import { DIFFICULTY, BUILDING_DEFS, UNIT_DEFS, AXIS_BASE, PLAYER_BASE, ECONOMY } from './config.js';
import { spawnBuilding, spawnUnit? } from './commands.js';
import { feedEvent } from './feed.js';

const AXIS_SOCKETS = [ // build spots near axis base, mirrored
  { x: 66, z: -44 },  // barracks 1
  { x: 88, z: -38 },  // factory 1
  { x: 60, z: -68 },  // barracks 2
  { x: 92, z: -72 },  // factory 2 (marshal)
];

export function initAI() {
  G.ai = { thinkT: 0, attackT: 75, socketsUsed: {barracks: 0, factory: 0} };
}

export function updateAI(dt) {
  const ai = G.ai; if (!ai) return;
  ai.thinkT -= dt; ai.attackT -= dt;
  if (ai.thinkT <= 0) { ai.thinkT = 1.0; think(); }
  if (ai.attackT <= 0) { tryAttack(); }
}

function axisUnits(type?) ...
function think() {
  const req = G.axis.req;
  const d = DIFFICULTY[G.difficulty];
  const buildings = G.buildings.filter(b => b.side==='axis');
  const bBarracks = buildings.filter(b=>b.type==='barracks');
  const bFactories = buildings.filter(b=>b.type==='factory');
  const maxBarracks = G.difficulty==='cadet' ? 1 : 2;
  const maxFactories = G.difficulty==='marshal' ? 2 : 1;
  // Build
  if (bBarracks.length < maxBarracks && req >= BUILDING_DEFS.barracks.cost + 40) {
    const s = AXIS_SOCKETS[ai.socketsUsed.barracks] ... place; G.axis.req -= cost; ai.socketsUsed.barracks++
  } else if (bFactories.length < maxFactories && bBarracks.length >= 1 && req >= BUILDING_DEFS.factory.cost + 40) { factory socket }
  // Train
  for (const b of buildings) {
    if (b.buildProgress < 1 || b.queue.length >= 2) continue;
    if (b.type === 'barracks') {
      const rifles = ...count rifle units axis
      const want = G.difficulty==='cadet' ? 4 : 7;
      if (rifles < want && req >= 100) queue rifle else if (req >= 140 && Math.random()<0.5) queue recon
    } else if (b.type === 'factory') {
      const tanks = count tank; const arty = count arty;
      if (req >= 260) {
        if (tanks >= 2 + arty * 2 && req >= 300) queue arty else queue tank
      }
    }
  }
  // Capture
  if (Math.random() < 0.5 || !ai.captureT || ai.captureT <= 0) {
    assign capture group: nearest flag not owned by axis; find up to 3 idle rifle/recon units (order idle); order attackmove to flag.
    ai.captureT = 12;
  } else ai.captureT -= 1;
}

function tryAttack() {
  const d = DIFFICULTY[G.difficulty];
  const military = G.units.filter(u => u.side==='axis');
  if (military.length >= d.aiAggro) {
    let target = null;
    // attack nearest player building (prefer HQ)
    const hqs = G.buildings.filter(b => b.side==='player' && b.type==='hq');
    target = hqs[0] || G.buildings.find(b=>b.side==='player');
    if (target) {
      for (const u of military) if (u.def && UNIT_DEFS[u.type].kind !== undefined) {
        u.order = { kind:'attackmove', x: target.group.position.x, z: target.group.position.z };
        u.anchor = { x: target.group.position.x, z: target.group.position.z };
      }
      feedEvent('Enemy armor advancing on your position!', 'axis');
      audio.alarm();
    }
    G.ai.attackT = G.difficulty==='marshal' ? 55 : G.difficulty==='officer' ? 70 : 95;
  } else G.ai.attackT = 12;
}
```

Queue unit: push to b.queue: {type, t: buildTime, total: buildTime}; deduct req at enqueue.

Socket placement validity: those sockets are in axis base flat zone — fine, but check not on road? They're off-road. Also avoid overlap between barracks socket 1 and factory socket 2... chosen coords are distinct.

Units for capture: prefer rifle. Send 2-3. Also AI should defend: units auto-acquire handles.

Edge case: AXIS has no barracks yet and no units to capture — capture assignment no-op.

Names from FACTIONS for feed: 'Axis' label — feed uses side styling.

