}
#start-btn:hover { transform: translateY(-2px); filter: brightness(1.06); box-shadow: 0 6px 0 #6d5620, 0 18px 44px rgba(214, 178, 94, 0.45); }
#start-btn:active { transform: translateY(2px); box-shadow: 0 2px 0 #6d5620, 0 6px 18px rgba(214, 178, 94, 0.3); }

.text-btn {
  background: none; border: none; color: var(--dim);
  font-size: 10px; letter-spacing: 2.4px; text-transform: uppercase;
  padding: 4px 0; text-align: left; border-bottom: 1px dashed #3a3c33; align-self: flex-start;
  transition: color 0.15s, border-color 0.15s;
}
.text-btn:hover { color: var(--brass); border-color: var(--brass-dim); }
.text-btn.small { border-bottom: none; }

#howto-panel {
  display: none; grid-template-columns: 1fr 1fr; gap: 18px;
  background: rgba(17, 19, 15, 0.82); border: 1px solid var(--line); border-radius: 4px;
  padding: 14px 18px; backdrop-filter: blur(4px);
}
#howto-panel.open { display: grid; }
.howto-col h3 { font-size: 10px; letter-spacing: 2.4px; color: var(--brass); text-transform: uppercase; margin: 10px 0 6px; }
.howto-col h3:first-child { margin-top: 0; }
.howto-col ul { list-style: none; display: flex; flex-direction: column; gap: 4px; }
.howto-col li { font-size: 11px; line-height: 1.55; color: #c9c7ba; }
.howto-col strong { color: var(--text); }

.menu-footer { display: flex; align-items: center; gap: 16px; margin-top: 2px; flex-wrap: wrap; }
.menu-credit { font-size: 9.5px; letter-spacing: 1px; color: #57564c; }

.menu-side-note {
  position: absolute; right: 3.2vw; bottom: 6vh; max-width: 250px;
  display: flex; flex-direction: column; gap: 10px; align-items: flex-end; text-align: right;
}
.side-note-line { width: 72px; height: 2px; background: var(--brass-dim); }
.side-note-text { font-size: 11.5px; font-style: italic; line-height: 1.7; color: rgba(232, 230, 218, 0.6); }

/* ---------- Pause ---------- */
.pause-inner, .end-inner {
  width: min(480px, calc(100% - 32px));
  padding: 28px 32px 26px; text-align: center;
  display: flex; flex-direction: column; align-items: center; gap: 14px;
}
.pause-kicker, .end-kicker { font-size: 9px; letter-spacing: 3.4px; color: var(--brass-dim); }
.pause-title { font-family: var(--font-stencil); font-size: 34px; letter-spacing: 4px; color: var(--text); }
.pause-sub { font-size: 12px; color: var(--dim); font-style: italic; }
.pause-buttons { display: flex; flex-direction: column; gap: 8px; width: 100%; }
.big-btn {
  padding: 12px 18px; border-radius: 4px; letter-spacing: 2px;
  font-family: var(--font-stencil); font-size: 15px;
  background: var(--panel-3); border: 1px solid var(--line); color: var(--text);
