}
.big-btn:hover { border-color: var(--brass); box-shadow: 0 0 14px rgba(214,178,94,0.22); }
.big-btn:active { transform: translateY(1px); }
.big-btn.primary { background: linear-gradient(180deg, #e8ca7a, #c9a44e); color: #14140e; border: none; box-shadow: 0 3px 0 #6d5620; }
.big-btn.danger { color: #eba08e; border-color: rgba(192, 72, 58, 0.5); }
.big-btn.danger:hover { border-color: var(--danger); box-shadow: 0 0 14px rgba(192,72,58,0.3); }
.pause-controls { display: flex; gap: 12px; flex-wrap: wrap; justify-content: center; font-size: 10px; color: var(--dim); }

/* ---------- End screen ---------- */
.end-title { font-family: var(--font-stencil); font-size: 74px; letter-spacing: 10px; line-height: 1; }
.end-title.victory { color: var(--brass); text-shadow: 0 0 44px rgba(214, 178, 94, 0.5); }
.end-title.defeat { color: var(--red); text-shadow: 0 0 44px rgba(217, 123, 90, 0.4); }
.end-sub { font-size: 13px; color: var(--dim); max-width: 42ch; line-height: 1.55; }
#end-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; width: 100%; }
.stat { background: rgba(0,0,0,0.3); border: 1px solid var(--line); border-radius: 4px; padding: 10px 6px; display: flex; flex-direction: column; gap: 4px; }
.stat-num { font-family: var(--font-mono); font-size: 21px; color: var(--brass); }
.stat-label { font-size: 8px; letter-spacing: 1.6px; text-transform: uppercase; color: var(--dim); }
.end-buttons { display: flex; flex-direction: column; gap: 8px; width: 100%; }

/* ============ Responsive / touch ============ */
@media (max-width: 1080px) {
  .tb-left { min-width: 0; }
  #game-map { display: none; }
  .pip-wrap span { display: none; }
  #game-name { font-size: 15px; }
}
@media (max-width: 820px) {
  #topbar { gap: 8px; padding: 6px 8px; }
  #factiton-badge { width: 30px; height: 30px; }
  #faction-badge { width: 30px; height: 30px; }
  #faction-badge svg { width: 19px; height: 19px; }
  .tb-center { gap: 8px; }
  #flag-pips { gap: 8px; }
  .pip { width: 21px; height: 21px; font-size: 10px; }
  .tb-timer-wrap { padding-left: 8px; }
  #game-timer { font-size: 16px; }
  #req-count { font-size: 19px; min-width: 38px; }
  .req-label { display: none; }
  .tb-btn { width: 34px; height: 34px; }
  #selection-panel { min-width: 0; max-width: 46vw; padding: 7px 9px; gap: 8px; bottom: 8px; left: 8px; }
  #sel-portrait { width: 46px; height: 46px; flex-basis: 46px; }
  #sel-portrait svg { width: 30px; height: 30px; }
  #sel-name { font-size: 12px; letter-spacing: 0.8px; white-space: normal; }
  #sel-sub { max-width: 150px; font-size: 9px; white-space: normal; }
  #command-card { min-width: 0; padding: 6px 8px; bottom: 8px; left: 50%; max-width: 52vw; }
  .cc-btn { width: 62px; min-height: 62px; }
  .cc-icon svg { width: 22px; height: 22px; }
  .cc-label { font-size: 7.5px; }
  .cc-cost { font-size: 8.5px; }
  #minimap-wrap { right: 8px; bottom: 8px; padding: 4px; }
  #minimap { width: 128px; height: 128px; }
  #minimap-label { font-size: 6.5px; letter-spacing: 2px; }
  #feed { top: 58px; max-width: 220px; }
  .feed-entry { font-size: 10px; }
  #menu { background: linear-gradient(180deg, rgba(7,8,6,0.9) 0%, rgba(7,8,6,0.72) 60%, rgba(7,8,6,0.45) 100%); align-items: flex-start; }
  .menu-inner { padding: 18px 18px 40px; }
  .menu-title { font-size: 64px; }
  .menu-side-note { display: none; }
  #howto-panel { grid-template-columns: 1fr; }
  .diff-btn { flex: 1 1 100%; }
  #game-timer, .req-panel { display: block; }
  .req-side { display: none; }
}
@media (max-height: 560px) and (orientation: landscape) {
  .menu-title { font-size: 52px; }
  .menu-brief { display: none; }
  #howto-panel { max-height: 34vh; overflow-y: auto; }
  .menu-inner { gap: 8px; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.001s !important; transition-duration: 0.15s !important; }
}

content.text:
Now main.js — the orchestrator. Let me write it carefully.

```js
import * as THREE from 'three';
import { G, resetState } from './state.js';
import { MAP_SIZE, PLAYER_BASE, AXIS_BASE, ECONOMY, FACTIONS, SKIRMISH_TIME, CAPTURE_POINTS } from './config.js';
import { buildWorld, terrainHeight } from './world.js';
import { spawnUnit, spawnBuilding } from './commands.js';
import { updateUnits, updateBuildings, updateFlags, updateEconomy, updateTimers, updateHealthBars } from './simulation.js';
import { updateProjectiles } from './combat.js';
import { initAI, updateAI } from './ai.js';
import { initUI, refreshCommandCard, tickCommandCard, tickMinimap, tickHUD, endGame, hideOverlay, showOverlay, exitPlacementMode, clickPlacement, screenToGround, enterPlacementMode } from './ui.js';
import { spawnMoveMarker, disposeAllEffects } from './effects.js';
import { feedEvent, showToast, hideToast } from './feed.js';
import { audio } from './audio.js';
import { setHealthBar? } no.
```

Scene setup:

```js
const container = document.getElementById('scene-container');
const scene = new THREE.Scene();
G.scene = scene;
scene.background = new THREE.Color(0x8e979e); // cold haze — warm sunset better? November ardennes overcast: 0x9aa3ab. Add gradient sky via big sphere? Let's use fog + background color 0xa3a8ad.
scene.fog = new THREE.Fog(0x9aa1a8, 90, 235);

const camera = new THREE.PerspectiveCamera(46, aspect, 0.5, 600);
const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 1.5));
renderer.setSize(w, h);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace default srgb in modern three.
container.appendChild(renderer.domElement);

// Lights
const hemi = new THREE.HemisphereLight(0xbcc8d4, 0x37342b, 0.75);
scene.add(hemi);
const sun = new THREE.DirectionalLight(0xffe6c0, 1.35);
sun.castShadow = true;
sun.shadow.mapSize.set(1024, 1024);
sun.shadow.camera.left = -78; right 78; top 78; bottom -78; near 10; far 260;
sun.shadow.bias = -0.0008;
scene.add(sun); scene.add(sun.target);
```

Sun follows camera target each frame: sun.position = target + offsetDir*110; sun.target.position = target; (shadow camera fixed ±78 covers 156 units — big but okay; resolution low but fine).

buildWorld(scene) → store world handles for teardown; G.flags = flags from return? buildWorld returns {world, terrain, clouds} but not flags — flags need to go into G.flags. Modify world.js return to include flags: return { world, terrain, clouds, flags }. Update G.flags = flags, and set each flag's colors initial (neutral). Do that now (edit world.js).

setupBattlefield():

```js
function teardownScene() {
  // Remove everything except lights
  const keep = [];
  scene.traverse? — easier: collect scene.children, remove all, dispose, re-add lights.
}
```

Implementation: keep references to hemi/sun/sun.target. 

```js
const persistent = [hemi, sun, sun.target];
for (const child of [...scene.children]) {
  if (persistent.includes(child)) continue;
  scene.remove(child);
  disposeTree(child);
}
function disposeTree(root){ root.traverse(o=>{ if(o.geometry) o.geometry.dispose(); const m=o.material; if(m){ if(Array.isArray(m)) m.forEach(mm=>{ mm.map?.dispose(); mm.dispose(); }); else { m.map?.dispose(); m.dispose(); } } }); }
resetState();
const built = buildWorld(scene);
G.flags = built.flags;
G.world = built.world;
// Spawn forces
spawnBuilding('player', 'hq', PLAYER_BASE.x, PLAYER_BASE.z, true);
spawnBuilding('axis', 'hq', AXIS_BASE.x, AXIS_BASE.z, true);
G.player = { req: ECONOMY.startReq, income: ECONOMY.baseIncome };
G.axis = { req: ECONOMY.startReq, income: ECONOMY.baseIncome };
initAI();
// Starting units — small wedge forward of each HQ
const p1 = spawnUnit('player', 'rifle', PLAYER_BASE.x + 7, PLAYER_BASE.z - 6);
const p2 = spawnUnit('player', 'rifle', PLAYER_BASE.x + 10, PLAYER_BASE.z + 1);
spawnUnit('player', 'recon', PLAYER_BASE.x + 4, PLAYER_BASE.z - 11);
spawnUnit('axis', 'rifle', AXIS_BASE.x - 7, AXIS_BASE.z + 6);
spawnUnit('axis', 'rifle', AXIS_BASE.x - 10, AXIS_BASE.z - 1);
spawnUnit('axis', 'recon', AXIS_BASE.x - 4, AXIS_BASE.z + 11);
// Give them initial stance and no selection
G.selection = [];
refreshCommandCard();
```

For menu: setupBattlefield then mode='menu'; HUD hidden; menu visible.

startOperation():
```js
setupBattlefield();  // fresh
G.time = 0; G.timeLeft = SKIRMISH_TIME; G.mode = 'playing';
hide menu/endscreen/pause; show #hud; refreshCommandCard();
feedEvent('Operation Iron Front — destroy the Axis HQ', 'neutral');
feedEvent('Capture flags A, B, C to fund the war effort', 'neutral');
```
Note setupBattlefield also used for menu — menu rebuilds battlefield each time (fresh units idle — fine for orbit view; units have animations frozen? In menu mode we don't update simulation, so units stand still — fine).

Actually for menu ambiance, I could run a lightweight ambient update (clouds drift + flag wave) — flag wave needs G.flags update (updateFlags does capture logic — not wanted in menu). I'll add ambient: clouds drift + flag cloth wave via small duplicated loop, or just call parts. Simpler: in menu mode, rotate the HQ antenna beacon (needs buildings update...). Keep menu simple: cloud drift only (iterate built.clouds) + camera orbit. And water none. OK.

Pause: toggle between playing/paused; show/hide #pause overlay; Esc or Space.

updateCamera(dt, realDt):
```js
if (G.mode === 'menu') {
  const t = clock elapsed; angle = t * 0.07; camera.position.set(Math.sin(angle)*95, 46 + Math.sin(t*0.3)*4, Math.cos(angle)*95); camera.lookAt(0, 3, 0); return;
}
// pan keys
const panSpeed = 46 * (G.cam.dist / 62);
