```js
() => {
  const G = window.__G;
  const cam = G.camera;
  const b = G.buildings.find(b=>b.side==='player'&&b.type==='hq');
  const v = b.group.position.clone(); v.y += 2;
  v.project(cam);
  const rect = G.renderer.domElement.getBoundingClientRect();
  const x = (v.x*0.5+0.5)*rect.width + rect.left;
  const y = (-v.y*0.5+0.5)*rect.height + rect.top;
  const ev = (type) => new PointerEvent(type, {clientX:x, clientY:y, button:0, pointerId:1, bubbles:true});
  G.renderer.domElement.dispatchEvent(ev('pointerdown'));
